		}
		switch {
		case isComment:
			comment++
		case strings.HasPrefix(trimmed, "[") || strings.HasPrefix(trimmed, "{") ||
			strings.HasPrefix(trimmed, "'") || strings.HasPrefix(trimmed, string(rune(34))):
			literal++
		default:
			code++
		}
